using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Reflection;
using System.IO.Compression;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace Nexus {
  public static class ManagedTests {
    static int checks;
    static void Check(bool value,string message){if(!value)throw new Exception("Managed: "+message);checks++;}
    static void Reject(Action action,string message){try{action();}catch{checks++;return;}throw new Exception("Managed: expected rejection "+message);}
    static byte[] Exe(){return File.ReadAllBytes(Assembly.GetExecutingAssembly().Location);}
    static byte[] Zip(Dictionary<string,byte[]> files){using(var stream=new MemoryStream()){using(var archive=new ZipArchive(stream,ZipArchiveMode.Create,true))foreach(var file in files)using(var output=archive.CreateEntry(file.Key).Open())output.Write(file.Value,0,file.Value.Length);return stream.ToArray();}}
    static byte[] Text(string value){return System.Text.Encoding.UTF8.GetBytes(value);}
    static PortEntry Entry(string id,string kind="Zip"){return new PortEntry{Id=id,Repository="test/"+id,Name=id,Platform="Xbox",PackageKind=kind,DiscoverExecutable=true,AssetPattern=kind=="Zip"?"^port.zip$":"^port.exe$",PlayNames=new string[0],ConfigNames=new string[0]};}
    static PortRelease Release(PortEntry entry,byte[] bytes,string version){return new PortRelease{Version=version,AssetName=entry.PackageKind=="Zip"?"port.zip":"port.exe",Size=bytes.Length,DownloadUrl=entry.ProjectUrl+"/releases/download/"+version+"/"+(entry.PackageKind=="Zip"?"port.zip":"port.exe")};}
    static Game Install(PortEntry entry,byte[] bytes,string version,string root,InstallInteraction interaction=null,IProgress<InstallProgress> progress=null,CancellationToken token=default(CancellationToken)){using(var catalog=new PortCatalog(new Bytes(bytes)))return catalog.Install(entry,Release(entry,bytes,version),root,progress,token,false,interaction).GetAwaiter().GetResult();}
    public static int Run(string parent){
      checks=0;string root=Path.Combine(parent,"managed");Directory.CreateDirectory(root);var single=Entry("single");byte[] one=Zip(new Dictionary<string,byte[]>{{"nested/Game.exe",Exe()},{"nested/ffmpeg.exe",Exe()}});var installed=Install(single,one,"v1.0.0",root);Check(Path.GetFileName(installed.Executable)=="Game.exe"&&UpdateManager.Managed(installed),"single application is discovered and registered without helper");Check(UpdateManager.Receipt(installed).files.Count==2,"receipt tracks package hashes for updates");
      string invalid=Path.Combine(root,"invalid.exe");File.WriteAllText(invalid,"not executable");Check(!PackageSupport.WindowsExecutable(invalid),"disguised non-PE rejected");string arm=Path.Combine(root,"arm.exe");var pe=Exe();int offset=BitConverter.ToInt32(pe,60);pe[offset+4]=0x64;pe[offset+5]=0xaa;File.WriteAllBytes(arm,pe);Check(!PackageSupport.WindowsExecutable(arm),"ARM64 rejected on x64 profile");
      var multiple=Entry("multiple");byte[] multi=Zip(new Dictionary<string,byte[]>{{"Game.exe",Exe()},{"Launcher.exe",Exe()}});Reject(()=>Install(multiple,multi,"v1",root),"ambiguous application cannot be guessed");Check(!Directory.Exists(Path.Combine(root,"multiple-v1")),"cancelled selection does not leave installed folder");
      int selected=0;var choice=new InstallInteraction{Choose=delegate(string folder,string[] choices,Game old){selected++;Check(choices.Length==2,"selection receives both real applications");return new LaunchSelection{Play="Game.exe",Configuration="Launcher.exe"};}};var chosen=Install(multiple,multi,"v2",root,choice);Check(selected==1&&Path.GetFileName(chosen.ConfigurationExecutable)=="Launcher.exe","in-Nexus choice records play and configuration");
      Reject(()=>Install(multiple,multi,"v3",root,new InstallInteraction{Choose=delegate{return new LaunchSelection{Play="..\\outside.exe"};}}),"selection cannot escape extracted package");
      var portable=Entry("portable","Executable");var executable=Install(portable,Exe(),"v1.0",root);Check(File.Exists(executable.Executable)&&UpdateManager.Managed(executable),"standalone executable is downloaded and registered without execution");
      var installer=Entry("installer","Installer");Reject(()=>Install(installer,Exe(),"v1.0",root),"installer cannot execute without interactive handler");int calls=0;string external=Path.Combine(root,"vendor-app.exe");File.WriteAllBytes(external,Exe());var vendor=Install(installer,Exe(),"v1.0",root,new InstallInteraction{RunInstaller=delegate(string file,Game old){calls++;Check(File.Exists(file),"installer is verified and staged before interaction");return Task.FromResult(new LaunchSelection{Play=external});}});Check(calls==1&&vendor.InstallationKind=="Installer"&&String.IsNullOrEmpty(vendor.ManagedInstallationRoot)&&UpdateManager.Managed(vendor),"vendor installation tracks selected application and release cache");
      var vendorNext=Install(installer,Exe(),"v1.1",root,new InstallInteraction{Previous=vendor,UpdateInPlace=true,RunInstaller=delegate(string file,Game old){calls++;return Task.FromResult(new LaunchSelection{Play=external});}});Check(calls==2&&vendorNext.Id==vendor.Id&&vendorNext.InstalledVersion=="v1.1","vendor update uses handler and preserves library identity");
      var update=Entry("update");byte[] first=Zip(new Dictionary<string,byte[]>{{"Game.exe",Exe()},{"engine.dll",Text("old")},{"removed.dll",Text("obsolete")},{"settings.json",Text("default")},{"defaults.ini",Text("default")}});var oldGame=Install(update,first,"v1.0.0",root);oldGame.Favorite=true;oldGame.Name="My custom title";oldGame.SourceGameDirectory="C:\\original-games";oldGame.Arguments="--custom";string target=oldGame.ManagedInstallationRoot;File.WriteAllText(Path.Combine(target,"settings.json"),"user setting");Directory.CreateDirectory(Path.Combine(target,"saves"));File.WriteAllText(Path.Combine(target,"saves","save.sav"),"progress");File.WriteAllText(Path.Combine(target,"my-file.txt"),"personal");
      byte[] second=Zip(new Dictionary<string,byte[]>{{"Game.exe",Exe()},{"engine.dll",Text("new")},{"settings.json",Text("new default")},{"defaults.ini",Text("new default")},{"new.txt",Text("new")}});var next=Install(update,second,"v1.1.0",root,new InstallInteraction{Previous=oldGame,UpdateInPlace=true});
      Check(next.ManagedInstallationRoot==target&&next.Id==oldGame.Id&&next.InstalledVersion=="v1.1.0","update keeps stable path and library identity");Check(next.Favorite&&next.Name=="My custom title"&&next.Arguments=="--custom"&&next.SourceGameDirectory==oldGame.SourceGameDirectory,"update preserves custom library settings");Check(File.ReadAllText(Path.Combine(target,"engine.dll"))=="new"&&!File.Exists(Path.Combine(target,"removed.dll")),"new binaries replace old and unchanged obsolete package file is removed");Check(File.ReadAllText(Path.Combine(target,"settings.json"))=="user setting"&&File.ReadAllText(Path.Combine(target,"defaults.ini"))=="new default","modified settings preserved while untouched defaults update");Check(File.ReadAllText(Path.Combine(target,"saves","save.sav"))=="progress"&&File.ReadAllText(Path.Combine(target,"my-file.txt"))=="personal","saves and untracked user files survive update");Check(Directory.Exists(next.UpdateBackupDirectory)&&File.ReadAllText(Path.Combine(next.UpdateBackupDirectory,"engine.dll"))=="old","complete old installation is kept as backup");Check(UpdateManager.Managed(next)&&UpdateManager.Receipt(next).version=="v1.1.0","receipt commits new version");
      var library=new Library();library.Games.Add(next);var store=new Store(Path.Combine(root,"store"));store.Save(library);var loaded=store.Load().Games.Single();Check(loaded.InstalledVersion==next.InstalledVersion&&loaded.UpdateBackupDirectory==next.UpdateBackupDirectory,"update metadata persists across restart");
      var bad=Release(update,second,"v1.2.0");bad.Digest="sha256:"+new string('0',64);using(var catalog=new PortCatalog(new Bytes(second)))Reject(()=>catalog.Install(update,bad,root,null,CancellationToken.None,false,new InstallInteraction{Previous=next,UpdateInPlace=true}).GetAwaiter().GetResult(),"failed checksum leaves installed version untouched");Check(File.ReadAllText(Path.Combine(target,"engine.dll"))=="new"&&UpdateManager.Receipt(next).version=="v1.1.0","integrity failure does not modify current installation");
      var cached=Release(update,second,"v1.2.0");cached.FromCache=true;using(var catalog=new PortCatalog(new Bytes(second)))Reject(()=>catalog.Install(update,cached,root,null,CancellationToken.None,false,new InstallInteraction{Previous=next,UpdateInPlace=true}).GetAwaiter().GetResult(),"stale cache cannot trigger update");
      Reject(()=>Install(update,second,"v1.0.0",root,new InstallInteraction{Previous=next,UpdateInPlace=true}),"downgrade rejected");Reject(()=>Install(update,second,"v1.1.0",root,new InstallInteraction{Previous=next,UpdateInPlace=true}),"same version cannot overwrite itself");
      for(int i=0;i<60;i++)File.WriteAllText(Path.Combine(target,"user-"+i+".txt"),"preserve");var cancellation=new CancellationTokenSource();var cancelProgress=new ImmediateProgress(p=>{if(p.Message.StartsWith("Preservando"))cancellation.Cancel();});Reject(()=>Install(update,second,"v1.2.0",root,new InstallInteraction{Previous=next,UpdateInPlace=true},cancelProgress,cancellation.Token),"cancellation during merge aborts before commit");Check(UpdateManager.Receipt(next).version=="v1.1.0"&&File.ReadAllText(Path.Combine(target,"user-59.txt"))=="preserve"&&!Directory.GetDirectories(root,".nexus-update-*").Any(),"cancelled merge retains installed files and cleans only its staging");
      UpdateManager.Rollback(next,oldGame);Check(File.ReadAllText(Path.Combine(target,"engine.dll"))=="old"&&UpdateManager.Managed(oldGame),"library-save failure can restore complete previous version");
      var legacy=Entry("legacy");var legacyGame=Install(legacy,first,"v1.0",root);var legacyReceipt=UpdateManager.Receipt(legacyGame);legacyReceipt.files=null;File.WriteAllText(Path.Combine(legacyGame.ManagedInstallationRoot,".nexus-install.json"),new JavaScriptSerializer().Serialize(legacyReceipt));File.WriteAllText(Path.Combine(legacyGame.ManagedInstallationRoot,"settings.json"),"legacy setting");var legacyNext=Install(legacy,second,"v1.1",root,new InstallInteraction{Previous=legacyGame,UpdateInPlace=true});Check(File.ReadAllText(Path.Combine(legacyNext.ManagedInstallationRoot,"settings.json"))=="legacy setting","old receipts without file manifest preserve configuration");
      Reject(()=>UpdateManager.EnsureClosed(new Game{Executable=Assembly.GetExecutingAssembly().Location}),"updating running executable rejected without killing process");
      var wrapped=Entry("wrapped");byte[] wrappedOld=Zip(new Dictionary<string,byte[]>{{"Port-v1/Game.exe",Exe()},{"Port-v1/Config.exe",Exe()},{"Port-v1/settings.json",Text("default")}});var wrappedGame=Install(wrapped,wrappedOld,"v1.0",root,new InstallInteraction{Choose=delegate{return new LaunchSelection{Play="Port-v1\\Game.exe",Configuration="Port-v1\\Config.exe",Arguments="--custom",ConfigurationArguments="--options"};}});string wrappedRoot=wrappedGame.ManagedInstallationRoot;Directory.CreateDirectory(Path.Combine(wrappedRoot,"Port-v1","game"));File.WriteAllText(Path.Combine(wrappedRoot,"Port-v1","game","owned.bin"),"owned");File.WriteAllText(Path.Combine(wrappedRoot,"Port-v1","settings.json"),"custom");wrappedGame.SourceGameDirectory=Path.Combine(wrappedRoot,"Port-v1","game");wrappedGame.GameContentSource=Path.Combine(wrappedRoot,"Port-v1");byte[] wrappedNew=Zip(new Dictionary<string,byte[]>{{"Port-v2/Game.exe",Exe()},{"Port-v2/Config.exe",Exe()},{"Port-v2/settings.json",Text("new default")}});var wrappedNext=Install(wrapped,wrappedNew,"v2.0",root,new InstallInteraction{Previous=wrappedGame,UpdateInPlace=true,Choose=delegate{throw new Exception("unchanged executable names should retain previous choice");}});Check(File.ReadAllText(Path.Combine(wrappedRoot,"Port-v2","game","owned.bin"))=="owned"&&File.ReadAllText(Path.Combine(wrappedRoot,"Port-v2","settings.json"))=="custom","versioned enclosing folder changes migrate data and custom settings");Check(wrappedNext.SourceGameDirectory==Path.Combine(wrappedRoot,"Port-v2","game")&&wrappedNext.GameContentSource==Path.Combine(wrappedRoot,"Port-v2")&&wrappedNext.Arguments=="--custom"&&wrappedNext.ConfigurationArguments=="--options","enclosing folder changes preserve launch choices and map internal source paths");
      Check(UpdateManager.Newer("v1.2.0","v1.3.0")&&!UpdateManager.Newer("v1.3.0","v1.2.0")&&!UpdateManager.Newer("v1.0.0","1.0")&&UpdateManager.Newer("v1.0.0-beta","v1.0.0")&&!UpdateManager.Newer("v1.0.0","v1.0.0-beta"),"version comparison respects older releases and stable promotion");
      var historyEntry=Entry("history");var serializer=new JavaScriptSerializer();var historyJson=serializer.Serialize(new[]{new{tag_name="v2.0",html_url=historyEntry.ProjectUrl+"/releases/tag/v2.0",draft=false,prerelease=false,assets=new[]{new{name="android.apk",size=10,browser_download_url=historyEntry.ProjectUrl+"/releases/download/v2.0/android.apk"}}},new{tag_name="v1.5",html_url=historyEntry.ProjectUrl+"/releases/tag/v1.5",draft=false,prerelease=false,assets=new[]{new{name="port.zip",size=10,browser_download_url=historyEntry.ProjectUrl+"/releases/download/v1.5/port.zip"}}}});Check(PortCatalog.ParseReleaseList(historyEntry,historyJson).Version=="v1.5","latest compatible Windows package is selected when newer release is Android-only");
      var badBytes=Text("not an executable");int badCalls=0;Reject(()=>Install(installer,badBytes,"v8.0",root,new InstallInteraction{RunInstaller=delegate{badCalls++;return Task.FromResult(new LaunchSelection{Play=external});}}),"invalid executable rejected before installer handler");Check(badCalls==0,"invalid installer never reaches execution handler");
      Check(UpdateManager.Newer("v1.0.0-rc9","v1.0.0-rc10")&&!UpdateManager.Newer("v1.0.0-rc10","v1.0.0-rc9"),"prerelease numeric suffix cannot downgrade");
      var rebuilt=Entry("rebuilt");var rebuiltGame=Install(rebuilt,one,"v1.0",root);var rebuiltReceipt=UpdateManager.Receipt(rebuiltGame);rebuiltReceipt.digest="sha256:"+new string('1',64);File.WriteAllText(Path.Combine(rebuiltGame.ManagedInstallationRoot,".nexus-install.json"),new JavaScriptSerializer().Serialize(rebuiltReceipt));var republished=Release(rebuilt,one,"v1.0");using(var hash=System.Security.Cryptography.SHA256.Create())republished.Digest="sha256:"+BitConverter.ToString(hash.ComputeHash(one)).Replace("-","").ToLowerInvariant();Check(UpdateManager.Available(rebuiltGame,republished),"republished same tag detected by published checksum");using(var catalog=new PortCatalog(new Bytes(one))){var rebuiltNext=catalog.Install(rebuilt,republished,root,null,CancellationToken.None,false,new InstallInteraction{Previous=rebuiltGame,UpdateInPlace=true}).GetAwaiter().GetResult();Check(!UpdateManager.Available(rebuiltNext,republished)&&rebuiltNext.Id==rebuiltGame.Id,"same-tag rebuild installs once and keeps library identity");}
      return checks;
    }
    class Bytes:HttpMessageHandler {readonly byte[] data;public Bytes(byte[] bytes){data=bytes;}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){RequestMessage=request,Content=new ByteArrayContent(data)});}}
    class ImmediateProgress:IProgress<InstallProgress>{readonly Action<InstallProgress> report;public ImmediateProgress(Action<InstallProgress> callback){report=callback;}public void Report(InstallProgress p){report(p);}}
  }
}
